const fs=require('node:fs');
const ids={Bulbasaur:'001',Gengar:'094',Alakazam:'065',Machamp:'068',Eevee:'133',Snorlax:'143'};
const catalog=require('F:/Pokemon Arcade/src/data/catalog.json');
const data={};for(const [name,id]of Object.entries(ids)){const f=catalog.forms.find(f=>f.id===Number(id));data[name]={id:Number(id),type:f.types.map(t=>t[0].toUpperCase()+t.slice(1)),stats:Object.values(f.stats),weight:f.weightKg};}
fs.writeFileSync('assets/roster-source.json',JSON.stringify({source:'PokéAPI bulk tables, existing locally validated catalog',pokemon:data},null,2));
(async()=>{await Promise.all(Object.entries(ids).map(async([name,id])=>{const p=`assets/models/${name}.glb`;if(!fs.existsSync(p)){const r=await fetch(`https://raw.githubusercontent.com/06wj/pokemon/master/public/models/${id}/model.glb`);if(!r.ok)throw Error(name+': '+r.status);fs.writeFileSync(p,Buffer.from(await r.arrayBuffer()));}const buf=fs.readFileSync(p);const j=JSON.parse(buf.subarray(20,20+buf.readUInt32LE(12)));console.log(name,buf.length,JSON.stringify(j.animations?.map(a=>a.name)));}));const chart={};await Promise.all(['normal','fire','water','electric','grass','ice','fighting','poison','ground','flying','psychic','bug','rock','ghost','dragon','dark','steel','fairy'].map(async(type)=>{const r=await fetch('https://pokeapi.co/api/v2/type/'+type);if(!r.ok)throw Error(type);const d=await r.json(),entry={};for(const [k,m]of [['double_damage_to',2],['half_damage_to',.5],['no_damage_to',0]])for(const t of d.damage_relations[k])entry[t.name[0].toUpperCase()+t.name.slice(1)]=m;chart[type[0].toUpperCase()+type.slice(1)]=entry;}));fs.writeFileSync('assets/type-chart.json',JSON.stringify(chart,null,2));})().catch(e=>{console.error(e);process.exit(1)});
